static void aot_load(AotHookCall *hc, int with_pc) {
    Context *ctx = hc->context;
    for (int i = 0; i < 15; i++) ctx->r[i] = hc->r[i];
    if (with_pc) ctx->r[15] = hc->r[15];
    ctx->n = hc->n != 0; ctx->z = hc->z != 0; ctx->c = hc->c != 0; ctx->v = hc->v != 0;
}

static void aot_store(AotHookCall *hc, int with_pc) {
    Context *ctx = hc->context;
    for (int i = 0; i < 15; i++) hc->r[i] = ctx->r[i];
    if (with_pc) hc->r[15] = ctx->r[15];
    hc->n = ctx->n; hc->z = ctx->z; hc->c = ctx->c; hc->v = ctx->v;
}

/* the hook runs the function the override replaced */
/* The host's hooks do their work after the original returns (widen the projection, scale the
   region, ...). Recompiled code leaves a function early when the time slice runs out or a system
   call needs the host (ctx->exit), and resumes it later from the middle, NOT through this
   override. A hook that post-processes then works on a half-finished result, and the finished
   one is never touched: that frame is drawn un-widened (a flicker every time a slice ends
   inside the function). So the original gets extra budget: short functions finish in one go. */
#define AOT_HOOK_LEND 16384

static void aot_run_original(AotHookCall *hc) {
    Context *ctx = hc->context;
    aot_load(hc, 0);
    if (UNLIKELY(++ctx->depth > RECOMP_DEPTH_LIMIT)) {
        ctx->depth--;
        ctx->exit = EXIT_UNWIND;
    } else {
        ctx->budget += AOT_HOOK_LEND;
        hc->original(ctx);
        ctx->budget -= AOT_HOOK_LEND;
        if (ctx->budget < 0) ctx->budget = 0;
        ctx->depth--;
    }
    if (ctx->exit) hc->reserved |= 1; /* the function was left early: see above */
    aot_store(hc, 1); /* r15: where the function returned to */
    hc->ran = 1;
}

/* the hook calls a guest function (r14 is its return address) and gets the registers back */
static void aot_call_guest(AotHookCall *hc, uint32_t target) {
    Context *ctx = hc->context;
    const uint32_t pc = ctx->r[15];
    const uint8_t thumb = ctx->thumb;
    aot_load(hc, 0);
    ctx->r[15] = target & ~1u;
    ctx->thumb = target & 1;
    if (UNLIKELY(++ctx->depth > RECOMP_DEPTH_LIMIT)) {
        ctx->depth--;
        ctx->exit = EXIT_UNWIND;
    } else {
        recomp_call(ctx);
        ctx->depth--;
    }
    aot_store(hc, 0);
    ctx->r[15] = pc;
    ctx->thumb = thumb;
}

static void aot_dispatch(Context *ctx, uint32_t index, Code original) {
    AotHookFn hook = azahar_aot_hooks[index];
    if (!hook) {
        CALL(original);
        return;
    }
    AotHookCall hc;
    hc.abi = AOT_HOOK_ABI;
    hc.index = index;
    for (int i = 0; i < 15; i++) hc.r[i] = ctx->r[i];
    hc.r[15] = ctx->r[14]; /* a hook that skips the function returns to the caller */
    hc.n = ctx->n; hc.z = ctx->z; hc.c = ctx->c; hc.v = ctx->v;
    hc.write_pages = ctx->write_pages;
    hc.context = ctx;
    hc.original = original;
    hc.ran = 0;
    hc.reserved = 0;
    hc.run_original = aot_run_original;
    hc.call_guest = aot_call_guest;
    hook(&hc);
    aot_load(&hc, 0);
    if (hc.ran) {
        ctx->r[15] = hc.r[15];
        return;
    }
    RETURN_TO(hc.r[15]);
}

